const inferDeckStorySection = (slide, index, totalSlides) => {
  const signal = `${slide?.title || ''} ${slide?.subtitle || ''} ${slide?.headline || ''}`.toLowerCase();
  const keywordMap = [
    { key: 'Problem', patterns: ['problem', 'pain', 'challenge', 'friction', 'gap'] },
    { key: 'Opportunity', patterns: ['opportunity', 'timing', 'why now', 'trend'] },
    { key: 'Product', patterns: ['product', 'solution', 'platform', 'workflow', 'demo'] },
    { key: 'Market', patterns: ['market', 'tam', 'sam', 'som', 'segment', 'customer'] },
    { key: 'Strategy', patterns: ['strategy', 'go to market', 'distribution', 'growth', 'roadmap'] },
    { key: 'Financials', patterns: ['financial', 'revenue', 'cac', 'ltv', 'unit economics', 'forecast'] },
    { key: 'Closing', patterns: ['close', 'closing', 'ask', 'next step', 'thank you'] },
  ];
  const matched = keywordMap.find((item) => item.patterns.some((pattern) => signal.includes(pattern)));
  if (matched) {
    return matched.key;
  }
  if (totalSlides <= 1) {
    return 'Opening';
  }
  const normalized = index / Math.max(1, totalSlides - 1);
  const bucket = Math.min(DECK_STORY_SECTIONS.length - 1, Math.floor(normalized * DECK_STORY_SECTIONS.length));
  return DECK_STORY_SECTIONS[bucket];
};

const createTitleSlide = (id, theme = 'light') => {
  const isDark = theme === 'dark';
  return {
    id: `slide-${id}`,
    layout: 'title',
    background: isDark ? '#111827' : '#ffffff',
    elements: [
      { id: `title-${id}`, type: 'text', content: 'Presentation Title', x: 100, y: 300, w: 800, h: 100, style: { fontSize: 64, fontWeight: 700, color: isDark ? '#ffffff' : '#111827', textAlign: 'center' } },
      { id: `subtitle-${id}`, type: 'text', content: 'Subtitle goes here', x: 200, y: 420, w: 600, h: 60, style: { fontSize: 32, fontWeight: 400, color: isDark ? '#9CA3AF' : '#4B5563', textAlign: 'center' } }
    ]
  };
};

const createBlankDeckSlide = (id = 1) => ({
  id,
  title: `Slide ${id}`,
  subtitle: '',
  accent: 'from-indigo-500 to-violet-500',
  designPresetKey: DECK_DESIGN_PRESETS[(Math.max(0, id - 1)) % DECK_DESIGN_PRESETS.length]?.key || DECK_DESIGN_PRESETS[0].key,
  headline: '',
  blurb: '',
  visualType: 'hero statement',
  layoutStyle: 'cinematic split',
  motionCue: 'Soft fade and stagger reveal',
  keyMetric: '',
  speakerNotes: '',
  section: '',
  footer: 'Original design 繚 Editable',
});

// Sub-component to cleanly handle the local video stream without cluttering the main render
const LocalVideoFeed = ({ stream, isCameraOn }) => {
  const videoRef = useRef(null);

  useEffect(() => {
    if (videoRef.current && stream) {
      videoRef.current.srcObject = stream;
    }
  }, [stream]);

  if (!isCameraOn || !stream) {
    return (
      <div className="w-full h-full bg-gray-800 flex items-center justify-center">
        <div className="w-16 h-16 rounded-full bg-gray-700 flex items-center justify-center text-gray-400 text-xl font-bold">
          You
        </div>
      </div>
    );
  }

  return (
    <video
      ref={videoRef}
      autoPlay
      muted
      playsInline
      className="w-full h-full object-cover"
    />
  );
};

const RoomStageFeed = ({ stream, placeholder }) => {
  const videoRef = useRef(null);

  useEffect(() => {
    if (videoRef.current) {
      videoRef.current.srcObject = stream || null;
    }
  }, [stream]);

  if (!stream) {
    return (
      <div className="w-full h-full flex items-center justify-center bg-gradient-to-br from-slate-900 via-slate-800 to-slate-700 text-slate-200">
        <div className="text-center">
          <div className="text-sm font-semibold">{placeholder}</div>
          <div className="text-xs text-slate-300 mt-1">Waiting for media input</div>
        </div>
      </div>
    );
  }

  return <video ref={videoRef} autoPlay muted playsInline className="w-full h-full object-cover" />;
};

const getFileSemanticBadge = (mat) => {
  const nameLower = (mat?.name || '').toLowerCase();
  const typeLower = (mat?.type || '').toLowerCase();
  const ext = (nameLower.split('.').pop() || typeLower || '').toLowerCase();

  // 1. PDF -> Red (#DC2626)
  if (ext === 'pdf' || typeLower === 'pdf') {
    return {
      category: 'pdf',
      bgHex: '#DC2626',
      iconColor: 'text-red-500 dark:text-red-400',
      label: 'PDF',
      svg: (
        <svg className="w-2.5 h-2.5 text-white" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M3.5 2H10L13.5 5.5V13.5C13.5 14.0523 13.0523 14.5 12.5 14.5H3.5C2.94772 14.5 2.5 14.0523 2.5 13.5V3C2.5 2.44772 2.94772 2 3.5 2Z" stroke="currentColor" strokeWidth="1.5" />
          <path d="M9.5 2V5.5H13.5" stroke="currentColor" strokeWidth="1.2" />
        </svg>
      )
    };
  }

  // 2. Microsoft Word / DOC / DOCX -> Blue (#2563EB)
  if (['doc', 'docx'].includes(ext) || ['word', 'doc', 'docx'].includes(typeLower)) {
    return {
      category: 'word',
      bgHex: '#2563EB',
      iconColor: 'text-blue-500 dark:text-blue-400',
      label: ext.toUpperCase() || 'DOC',
      svg: (
        <svg className="w-2.5 h-2.5 text-white" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M3.5 2H10.5L13.5 5V13.5C13.5 14.0523 13.0523 14.5 12.5 14.5H3.5C2.94772 14.5 2.5 14.0523 2.5 13.5V3C2.5 2.44772 2.94772 2 3.5 2Z" stroke="currentColor" strokeWidth="1.5" />
          <path d="M10 2V5.5H13.5" stroke="currentColor" strokeWidth="1.2" />
        </svg>
      )
    };
  }

  // 3. Microsoft Excel / XLS / XLSX / CSV / ODS -> Green (#059669)
  if (['xls', 'xlsx', 'csv', 'ods'].includes(ext) || ['excel', 'spreadsheet', 'csv'].includes(typeLower)) {
    return {
      category: 'excel',
      bgHex: '#059669',
      iconColor: 'text-emerald-500 dark:text-emerald-400',
      label: ext === 'csv' ? 'CSV' : 'XLS',
      svg: (
        <svg className="w-2.5 h-2.5 text-white" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
          <rect x="2.5" y="2.5" width="11" height="11" rx="1.5" stroke="currentColor" strokeWidth="1.5" />
          <path d="M2.5 6.5H13.5" stroke="currentColor" strokeWidth="1.2" />
          <path d="M2.5 10.5H13.5" stroke="currentColor" strokeWidth="1.2" />
          <path d="M6.5 6.5V13.5" stroke="currentColor" strokeWidth="1.2" />
        </svg>
      )
    };
  }

  // 4. Microsoft PowerPoint / PPT / PPTX / KEY -> Orange (#D97706)
  if (['ppt', 'pptx', 'key'].includes(ext) || ['powerpoint', 'presentation', 'ppt'].includes(typeLower)) {
    return {
      category: 'powerpoint',
      bgHex: '#D97706',
      iconColor: 'text-amber-500 dark:text-amber-400',
      label: ext.toUpperCase() || 'PPT',
      svg: (
        <svg className="w-2.5 h-2.5 text-white" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
          <rect x="2" y="2.5" width="12" height="8.5" rx="1.5" stroke="currentColor" strokeWidth="1.5" />
          <path d="M5.5 14L8 11L10.5 14" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      )
    };
  }

  // 5. Regaarder Document (Native) -> Purple (#7C3AED)
  if (mat?.isRegaarderDoc || typeLower === 'regaarder_doc' || typeLower === 'regaarder_document' || ext === 'rgdoc' || ext === 'regaarder') {
    return {
      category: 'regaarder_doc',
      bgHex: '#7C3AED',
      iconColor: 'text-purple-500 dark:text-purple-400',
      label: 'RGD',
      svg: (
        <svg className="w-2.5 h-2.5 text-white" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M3.5 2H10.5L13.5 5V13.5C13.5 14.0523 13.0523 14.5 12.5 14.5H3.5C2.94772 14.5 2.5 14.0523 2.5 13.5V3C2.5 2.44772 2.94772 2 3.5 2Z" stroke="currentColor" strokeWidth="1.5" />
          <path d="M10 2V5.5H13.5" stroke="currentColor" strokeWidth="1.2" />
        </svg>
      )
    };
  }

  // 6. Regaarder Sheets -> Green (#059669)
  if (mat?.isRegaarderSheet || typeLower === 'regaarder_sheet' || typeLower === 'regaarder_sheets' || ext === 'rgsheet') {
    return {
      category: 'regaarder_sheet',
      bgHex: '#059669',
      iconColor: 'text-emerald-500 dark:text-emerald-400',
      label: 'RGS',
      svg: (
        <svg className="w-2.5 h-2.5 text-white" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
          <rect x="2.5" y="2.5" width="11" height="11" rx="1.5" stroke="currentColor" strokeWidth="1.5" />
          <path d="M2.5 6.5H13.5" stroke="currentColor" strokeWidth="1.2" />
          <path d="M2.5 10.5H13.5" stroke="currentColor" strokeWidth="1.2" />
          <path d="M6.5 6.5V13.5" stroke="currentColor" strokeWidth="1.2" />
        </svg>
      )
    };
  }

  // 7. Regaarder Presentation / Deck -> Orange (#D97706)
  if (mat?.isRegaarderDeck || typeLower === 'regaarder_deck' || typeLower === 'regaarder_presentation' || ext === 'rgdeck') {
    return {
      category: 'regaarder_deck',
      bgHex: '#D97706',
      iconColor: 'text-amber-500 dark:text-amber-400',
      label: 'RGD',
      svg: (
        <svg className="w-2.5 h-2.5 text-white" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
          <rect x="2" y="2.5" width="12" height="8.5" rx="1.5" stroke="currentColor" strokeWidth="1.5" />
          <path d="M5.5 14L8 11L10.5 14" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      )
    };
  }

  // 8. Plain text / TXT / MD -> Neutral Gray (#64748B)
  if (['txt', 'md', 'text', 'markdown', 'log'].includes(ext) || ['text', 'txt', 'plain'].includes(typeLower)) {
    return {
      category: 'text',
      bgHex: '#64748B',
      iconColor: 'text-slate-500 dark:text-zinc-400',
      label: ext.toUpperCase() || 'TXT',
      svg: (
        <svg className="w-2.5 h-2.5 text-white" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M3.5 2H10.5L13.5 5V13.5C13.5 14.0523 13.0523 14.5 12.5 14.5H3.5C2.94772 14.5 2.5 14.0523 2.5 13.5V3C2.5 2.44772 2.94772 2 3.5 2Z" stroke="currentColor" strokeWidth="1.5" />
          <path d="M10 2V5.5H13.5" stroke="currentColor" strokeWidth="1.2" />
        </svg>
      )
    };
  }

  // Default / generic -> Neutral Gray (#64748B)
  return {
    category: 'generic',
    bgHex: '#64748B',
    iconColor: 'text-slate-500 dark:text-zinc-400',
    label: (ext || 'FILE').substring(0, 4).toUpperCase(),
    svg: (
      <svg className="w-2.5 h-2.5 text-white" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
        <path d="M3.5 2H10.5L13.5 5V13.5C13.5 14.0523 13.0523 14.5 12.5 14.5H3.5C2.94772 14.5 2.5 14.0523 2.5 13.5V3C2.5 2.44772 2.94772 2 3.5 2Z" stroke="currentColor" strokeWidth="1.5" />
        <path d="M10 2V5.5H13.5" stroke="currentColor" strokeWidth="1.2" />
      </svg>
    )
  };
};

