  const parseRichTextToJsx = (text) => {
    if (!text) return null;
    const str = String(text);

    let markdown = str
      .replace(/<strong[^>]*>(.*?)<\/strong>/gi, '**$1**')
      .replace(/<b[^>]*>(.*?)<\/b>/gi, '**$1**')
      .replace(/<em[^>]*>(.*?)<\/em>/gi, '*$1*')
      .replace(/<i[^>]*>(.*?)<\/i>/gi, '*$1*')
      .replace(/<[^>]+>/g, '');

    const parts = [];
    const regex = /(\*\*\*[\s\S]*?\*\*\*|\*\*[\s\S]*?\*\*|\*[\s\S]*?\*|`[\s\S]*?`)/g;
    let lastIndex = 0;
    let match;

    while ((match = regex.exec(markdown)) !== null) {
      if (match.index > lastIndex) {
        parts.push({ text: markdown.substring(lastIndex, match.index), bold: false, italic: false });
      }
      const matchedText = match[0];
      if (matchedText.startsWith('***') && matchedText.endsWith('***')) {
        parts.push({ text: matchedText.slice(3, -3), bold: true, italic: true });
      } else if (matchedText.startsWith('**') && matchedText.endsWith('**')) {
        parts.push({ text: matchedText.slice(2, -2), bold: true, italic: false });
      } else if (matchedText.startsWith('*') && matchedText.endsWith('*')) {
        parts.push({ text: matchedText.slice(1, -1), bold: false, italic: true });
      } else {
        parts.push({ text: matchedText, bold: false, italic: false });
      }
      lastIndex = regex.lastIndex;
    }

    if (lastIndex < markdown.length) {
      parts.push({ text: markdown.substring(lastIndex), bold: false, italic: false });
    }

    if (parts.length === 0) {
      return str;
    }

    return parts.map((part, idx) => (
      <span
        key={idx}
        className={`${part.bold ? 'font-bold' : 'font-normal'} ${part.italic ? 'italic' : ''}`}
      >
        {part.text}
      </span>
    ));
  };

  const stripHtml = (html) => {
    if (!html) return '';
    const tmp = document.createElement('div');
    tmp.innerHTML = String(html);
    return (tmp.textContent || tmp.innerText || '').replace(/^#+\s*/, '').replace(/<[^>]*>?/gm, '').trim();
  };

  const findOutlineItem = (tree, id) => {
    if (!Array.isArray(tree)) return null;
    for (const item of tree) {
      if (item.id === id) return item;
      if (item.subsections && item.subsections.length > 0) {
        const subFound = findOutlineItem(item.subsections, id);
        if (subFound) return subFound;
      }
    }
    return null;
  };

  const updateOutlineItemTitle = (tree, id, newTitle) => {
    if (!Array.isArray(tree)) return [];
    const clean = stripHtml(newTitle);
    return tree.map((item) => {
      if (item.id === id) {
        return { ...item, title: clean, plainText: clean };
      }
      if (item.subsections && item.subsections.length > 0) {
        return {
          ...item,
          subsections: updateOutlineItemTitle(item.subsections, id, newTitle),
        };
      }
      return item;
    });
  };

  const deleteOutlineItem = (tree, id) => {
    if (!Array.isArray(tree)) return [];
    return tree
      .filter((item) => item.id !== id)
      .map((item) => {
        if (item.subsections && item.subsections.length > 0) {
          return {
            ...item,
            subsections: deleteOutlineItem(item.subsections, id),
          };
        }
        return item;
      });
  };

  const toggleOutlineItemStatus = (tree, id) => {
    if (!Array.isArray(tree)) return [];
    return tree.map((item) => {
      if (item.id === id) {
        return { ...item, completed: !item.completed };
      }
      if (item.subsections && item.subsections.length > 0) {
        return {
          ...item,
          subsections: toggleOutlineItemStatus(item.subsections, id),
        };
      }
      return item;
    });
  };

  const toggleOutlineItemExpanded = (tree, id) => {
    if (!Array.isArray(tree)) return [];
    return tree.map((item) => {
      if (item.id === id) {
        return { ...item, expanded: !item.expanded };
      }
      if (item.subsections && item.subsections.length > 0) {
        return {
          ...item,
          subsections: toggleOutlineItemExpanded(item.subsections, id),
        };
      }
      return item;
    });
  };

  const addSubsectionToTree = (tree, parentId) => {
    const newSubId = `sub-${Date.now()}`;
    const newSubItem = {
      id: newSubId,
      title: 'Untitled Subsection',
      plainText: 'Untitled Subsection',
      progress: 0,
      completed: false,
      level: 2,
      subsections: [],
      expanded: true,
    };

    const updateTree = (nodes) => {
      if (!Array.isArray(nodes)) return [];
      return nodes.map((node) => {
        if (node.id === parentId) {
          return {
            ...node,
            expanded: true,
            subsections: [...(node.subsections || []), newSubItem],
          };
        }
        if (node.subsections && node.subsections.length > 0) {
          return {
            ...node,
            subsections: updateTree(node.subsections),
          };
        }
        return node;
      });
    };

    const updatedTree = updateTree(tree);
    return { updatedTree, newSubId };
  };

  const extractHierarchicalOutline = (htmlString = docBodyHtml, titleString = docTitle) => {
    const rawItems = [];

    const addCandidate = (title, plainText, level) => {
      const cleanPlain = String(plainText || '').replace(/^#+\s*/, '').replace(/^[*_\-~`\s]+/, '').trim();
      if (!cleanPlain || cleanPlain.length < 2 || cleanPlain.length > 180) return;
      if (/^(untitled(\s+(document|section|page))?|unsaved\s+draft|type\s+\/\s+to\s+insert.*|new\s+document)$/i.test(cleanPlain)) return;
      if (rawItems.some((item) => item.plainText === cleanPlain)) return;

      rawItems.push({
        title: String(title || cleanPlain).trim(),
        plainText: cleanPlain,
        level: Math.min(Math.max(level, 1), 3),
      });
    };

    const getLevelFromElement = (el) => {
      const tag = el.tagName?.toLowerCase();
      if (tag === 'h1') return 1;
      if (tag === 'h2') return 2;
      if (tag === 'h3' || tag === 'h4' || tag === 'h5' || tag === 'h6') return 3;

      const style = el.getAttribute('style') || '';
      if (/font-size:\s*(?:2[4-9]|[3-9]\d)px/.test(style)) return 1;
      if (/font-size:\s*(?:1[9-9]|2[0-3])px/.test(style)) return 2;
      if (/font-size:\s*(?:1[6-8])px/.test(style)) return 3;

      if (el.classList?.contains('text-3xl') || el.classList?.contains('text-2xl')) return 1;
      if (el.classList?.contains('text-xl') || el.classList?.contains('text-lg')) return 2;

      return 2;
    };

    // PASS 1: Scan DOM Elements in blankBodyRef
    if (blankBodyRef.current) {
      const allElements = Array.from(blankBodyRef.current.querySelectorAll('h1, h2, h3, h4, h5, h6, p, li, div, blockquote'));
      allElements.forEach((el) => {
        const text = String(el.textContent || '').trim();
        const rawHtml = String(el.innerHTML || '').trim();
        if (!text || text.length < 3 || text.length > 180) return;

        const tag = el.tagName?.toLowerCase();
        let level = 0;

        if (/^h[1-6]$/.test(tag)) {
          level = getLevelFromElement(el);
        } else if (/^#+\s+/.test(text)) {
          if (/^#\s+/.test(text)) level = 1;
          else if (/^##\s+/.test(text)) level = 2;
          else level = 3;
        } else {
          const hasBoldChild = el.querySelector('strong, b, [style*="font-weight: 700"], [style*="font-weight:bold"]');
          const isEndingSymbol = text.endsWith(':') || text.endsWith('?');
          const isNumberedHeader = /^(?:section|part|step|\d+\.|\d+\.\d+)\b/i.test(text);

          if (hasBoldChild || isEndingSymbol || isNumberedHeader) {
            level = isNumberedHeader && /^\d+\.\d+/.test(text) ? 3 : 2;
          }
        }

        if (level > 0) {
          const firstBoldChild = el.querySelector('strong, b');
          if (firstBoldChild && text.length > 80) {
            const boldText = firstBoldChild.textContent?.trim();
            if (boldText && boldText.length >= 3 && boldText.length < 100) {
              addCandidate(firstBoldChild.innerHTML || boldText, boldText, level);
              return;
            }
          }
          addCandidate(rawHtml || text, text, level);
        }
      });
    }

    // PASS 2: Parse HTML / Text Blocks (fallback or supplement if candidates are few)
    if (rawItems.length < 3 && (htmlString || titleString)) {
      const tempDiv = document.createElement('div');
      tempDiv.innerHTML = htmlString || '';
      const blockElements = Array.from(tempDiv.querySelectorAll('h1, h2, h3, h4, h5, h6, p, li, div'));

      if (blockElements.length > 0) {
        blockElements.forEach((el) => {
          const text = String(el.textContent || '').trim();
          const rawHtml = String(el.innerHTML || '').trim();
          if (!text || text.length < 3 || text.length > 180) return;

          let level = 0;
          const tag = el.tagName?.toLowerCase();

          if (tag === 'h1' || /^#\s+/.test(text)) level = 1;
          else if (tag === 'h2' || /^##\s+/.test(text)) level = 2;
          else if (tag === 'h3' || tag === 'h4' || tag === 'h5' || tag === 'h6' || /^###+\s+/.test(text)) level = 3;
          else if (text.endsWith(':') || text.endsWith('?') || /^\d+\.\s+/.test(text) || /^\*\*[^*]+\*\*/.test(text) || /<strong|<b>/i.test(rawHtml)) {
            level = 2;
          }

          if (level > 0) {
            addCandidate(rawHtml || text, text, level);
          }
        });
      }

      // PASS 3: Raw line splitting (for plain text pasted without tags)
      const fullText = (tempDiv.innerText || tempDiv.textContent || '').trim();
      const lines = fullText.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);

      lines.forEach((line) => {
        let level = 0;
        if (/^#\s+/.test(line)) level = 1;
        else if (/^##\s+/.test(line)) level = 2;
        else if (/^###+\s+/.test(line)) level = 3;
        else if (line.length < 100 && (line.endsWith(':') || line.endsWith('?') || /^\d+\.\s+/.test(line) || /^\*\*[^*]+\*\*/.test(line))) {
          level = 2;
        }

        if (level > 0) {
          addCandidate(line, line, level);
        }
      });
    }

    // PASS 4: Fallback to document title if still empty (only for valid custom document titles)
    if (rawItems.length === 0 && titleString && !/^(untitled(\s+(document|section|page))?|unsaved\s+draft|new\s+document)$/i.test(String(titleString).trim())) {
      addCandidate(titleString, titleString, 1);
    }

    const tree = [];
    let currentH1 = null;
    let currentH2 = null;

    rawItems.forEach((item, index) => {
      const sectionNode = {
        id: `sec-${index}-${Date.now()}-${Math.random().toString(36).substr(2, 4)}`,
        title: item.title,
        plainText: item.plainText,
        level: item.level,
        progress: 0,
        completed: false,
        subsections: [],
        expanded: true,
      };

      if (item.level === 1) {
        tree.push(sectionNode);
        currentH1 = sectionNode;
        currentH2 = null;
      } else if (item.level === 2) {
        if (currentH1) {
          currentH1.subsections.push(sectionNode);
        } else {
          tree.push(sectionNode);
        }
        currentH2 = sectionNode;
      } else {
        if (currentH2) {
          currentH2.subsections.push(sectionNode);
        } else if (currentH1) {
          currentH1.subsections.push(sectionNode);
        } else {
          tree.push(sectionNode);
        }
      }
    });

    return tree;
  };

  const [activeEmojiEl, setActiveEmojiEl] = useState(null);
  const [emojiControlsPosition, setEmojiControlsPosition] = useState({ top: 0, left: 0 });
  const [savedEmojis, setSavedEmojis] = useState(() => {
    try {
      return JSON.parse(localStorage.getItem('rc.savedEmojis') || '[]');
    } catch {
      return [];
    }
  });
  const [showDeckComments, setShowDeckComments] = useState(false);
  const [isPresentingDeck, setIsPresentingDeck] = useState(false);
  const [showDeckNotes, setShowDeckNotes] = useState(false);
  const [deckTimerSeconds, setDeckTimerSeconds] = useState(0);
  const [deckTimerActive, setDeckTimerActive] = useState(false);
  const [deckSlashMenu, setDeckSlashMenu] = useState({
    open: false,
    top: 0,
    left: 0,
    bottom: 'auto',
    filterText: '',
    activeIndex: 0,
    range: null
  });

  useEffect(() => {
    let interval;
    if (deckTimerActive) {
      interval = setInterval(() => {
        setDeckTimerSeconds(s => s + 1);
      }, 1000);
    } else if (!deckTimerActive && deckTimerSeconds !== 0) {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [deckTimerActive, deckTimerSeconds]);

  useEffect(() => {
    window.bindDragHandler = (element) => {
      let isDragging = false;
      element.onmousedown = (e) => {
        if (element.style.position !== 'absolute') return;
        isDragging = true;
        let startX = e.clientX - element.offsetLeft;
        let startY = e.clientY - element.offsetTop;
        
        const handleMouseMove = (moveEvent) => {
          if (!isDragging) return;
          element.style.left = (moveEvent.clientX - startX) + 'px';
          element.style.top = (moveEvent.clientY - startY) + 'px';
        };
        
        const handleMouseUp = () => {
          isDragging = false;
          document.removeEventListener('mousemove', handleMouseMove);
          document.removeEventListener('mouseup', handleMouseUp);
          if (blankBodyRef.current) {
            setDocBodyHtml(blankBodyRef.current.innerHTML);
          }
        };
        
        document.addEventListener('mousemove', handleMouseMove);
        document.addEventListener('mouseup', handleMouseUp);
      };
    };

    window.handleEmojiClick = (event, element) => {
      event.preventDefault();
      event.stopPropagation();
      const rect = element.getBoundingClientRect();
      const editorRect = blankBodyRef.current?.getBoundingClientRect();
      setEmojiControlsPosition({
        top: rect.bottom - (editorRect?.top || 0) + (blankBodyRef.current?.scrollTop || 0) + 8,
        left: rect.left - (editorRect?.left || 0) + (blankBodyRef.current?.scrollLeft || 0),
      });
      setActiveEmojiEl(element);
    };

    window.showCreateEmojiForm = (boxId) => {
      const menuOpts = document.getElementById(`${boxId}_menu_options`);
      const createForm = document.getElementById(`${boxId}_create_form`);
      if (menuOpts) menuOpts.style.display = 'none';
      if (createForm) createForm.style.display = 'flex';
    };

    window.showSavedEmojisList = (boxId) => {
      const menuOpts = document.getElementById(`${boxId}_menu_options`);
      const listEl = document.getElementById(`${boxId}_saved_list`);
      if (menuOpts) menuOpts.style.display = 'none';
      if (listEl) {
        listEl.style.display = 'flex';
        listEl.style.flexWrap = 'wrap';
        
        const saved = JSON.parse(localStorage.getItem('rc.savedEmojis') || '[]');
        if (saved.length === 0) {
          listEl.innerHTML = `<span style="font-size:11px;color:#64748b;padding:4px;">No saved emojis yet.</span>`;
        } else {
          listEl.innerHTML = '';
          saved.forEach((item) => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.style.fontSize = '24px';
            btn.style.background = 'none';
            btn.style.border = 'none';
            btn.style.cursor = 'pointer';
            btn.style.padding = '4px';
            btn.style.borderRadius = '4px';
            btn.style.display = 'inline-flex';
            btn.style.alignItems = 'center';
            btn.style.justifyContent = 'center';
            btn.style.color = item.color || 'inherit';
            if (item.background) btn.style.backgroundColor = item.background;
            btn.title = `Size: ${item.fontSize || '24px'}, Color: ${item.color || 'Default'}`;
            btn.textContent = item.emoji;
            
            btn.onclick = () => {
              const liveContainer = document.getElementById(boxId);
              if (liveContainer && liveContainer.parentNode) {
                const emojiSpan = document.createElement('span');
                emojiSpan.className = 'inline-ai-emoji';
                emojiSpan.setAttribute('contenteditable', 'false');
                emojiSpan.setAttribute('draggable', 'true');
                emojiSpan.style.display = 'inline-block';
                emojiSpan.style.cursor = 'pointer';
                emojiSpan.style.fontSize = item.fontSize || '24px';
                emojiSpan.style.color = item.color || 'inherit';
                if (item.background) emojiSpan.style.backgroundColor = item.background;
                emojiSpan.style.userSelect = 'none';
                emojiSpan.style.position = item.position || 'relative';
                if (item.left) emojiSpan.style.left = item.left;
                if (item.top) emojiSpan.style.top = item.top;
                emojiSpan.textContent = item.emoji;
                emojiSpan.setAttribute('onclick', `window.handleEmojiClick(event, this)`);
                
                if (item.position === 'absolute') {
                  window.bindDragHandler(emojiSpan);
                }
                
                liveContainer.parentNode.insertBefore(emojiSpan, liveContainer);
                liveContainer.remove();
                
                if (blankBodyRef.current) {
                  setDocBodyHtml(blankBodyRef.current.innerHTML);
                }
              }
            };
            listEl.appendChild(btn);
          });
        }
      }
    };

    const handleOutsideClick = (e) => {
      if (shareMenuRef.current && !shareMenuRef.current.contains(e.target)) {
        setShareModalOpen(false);
      }
      if (composeShareMenuRef.current && !composeShareMenuRef.current.contains(e.target)) {
        setShareModalOpen(false);
      }
      if (profileMenuRef.current && !profileMenuRef.current.contains(e.target)) {
        setProfileMenuOpen(false);
      }
      if (composeProfileMenuRef.current && !composeProfileMenuRef.current.contains(e.target)) {
        setComposeProfileMenuOpen(false);
      }
      if (replayPanelRef.current && !replayPanelRef.current.contains(e.target)) {
        setReplayPanelOpen(false);
        setIsReplayPlaying(false);
      }
      if (emojiControlsRef.current && !emojiControlsRef.current.contains(e.target)) {
        setActiveEmojiEl(null);
      }
      if (pageOptionsMenuRef.current && !pageOptionsMenuRef.current.contains(e.target)) {
        setPageOptionsMenuOpen(false);
      }
      if (headerContextMenuRef.current && !headerContextMenuRef.current.contains(e.target)) {
        setHeaderContextMenu({ open: false, x: 0, y: 0, type: '', index: -1 });
      }

      // Dismiss Compose Dropdowns on Outside Click/Tap
      if (e.target && typeof e.target.closest === 'function') {
        if (openDropdown !== null && !e.target.closest('.compose-format-dropdown-container')) {
          setOpenDropdown(null);
        }
        if (pageSizeDropdownOpen && !e.target.closest('.page-size-dropdown-container')) {
          setPageSizeDropdownOpen(false);
        }
        if (pageMarginDropdownOpen && !e.target.closest('.page-margin-dropdown-container')) {
          setPageMarginDropdownOpen(false);
        }
        if (docStateDropdownOpen && !e.target.closest('.doc-state-dropdown-container')) {
          setDocStateDropdownOpen(false);
        }
        if (insertDropdownOpen && !e.target.closest('.compose-insert-dropdown-container')) {
          setInsertDropdownOpen(false);
        }
        if (listDropdownOpen && !e.target.closest('.compose-list-dropdown-container')) {
          setListDropdownOpen(false);
        }
      }

      if (e.target && typeof e.target.closest === 'function' && !e.target.closest('.absolute.z-\\[100\\]')) {
        setSelectedSheetOverlayId(null);
      }
      
      if (sheetChartMenuRef.current && !sheetChartMenuRef.current.contains(e.target)) {
        setSheetChartMenu({ open: false, left: 0, top: 0, anchorCell: null });
      }

      if (sheetShapeMenuRef.current && !sheetShapeMenuRef.current.contains(e.target)) {
        setSheetShapeMenu({ open: false, left: 0, top: 0, anchorCell: null });
      }

      if (sheetTablePresetMenuRef.current && !sheetTablePresetMenuRef.current.contains(e.target)) {
        setSheetTablePresetMenu(prev => ({ ...prev, open: false }));
      }

      if (slashMenuRef.current?.open && slashMenuContainerRef.current && !slashMenuContainerRef.current.contains(e.target)) {
        setSlashMenu({ open: false, left: 0, top: 0, bottom: 'auto', filterText: '', activeIndex: 0, range: null });
      }
      if (deckSlashMenuRef.current?.open && deckSlashMenuContainerRef.current && !deckSlashMenuContainerRef.current.contains(e.target)) {
        setDeckSlashMenu({ open: false, left: 0, top: 0, bottom: 'auto', filterText: '', activeIndex: 0, range: null });
      }
      if (sheetSlashMenuRef.current?.open && sheetSlashMenuContainerRef.current && !sheetSlashMenuContainerRef.current.contains(e.target)) {
        setSheetSlashMenu({ open: false, left: 0, top: 0, bottom: 'auto', filterText: '', activeIndex: 0, anchorCell: null });
      }
      if (watermarkMenuRef.current && !watermarkMenuRef.current.contains(e.target)) {
        if (!e.target.closest || !e.target.closest('[data-watermark-trigger="true"]')) {
          setShowWatermarkMenu(false);
        }
      }
      if (linkPopoverRef.current && !linkPopoverRef.current.contains(e.target)) {
        setLinkPopover(prev => ({ ...prev, open: false }));
      }
      if (commentPopoverRef.current && !commentPopoverRef.current.contains(e.target)) {
        setHoveredCommentId(null);
        setCommentPopover(prev => {
          if (prev.open) {
            setTimeout(() => {
              setComments(cs => {
                const c = cs.find(x => x.id === prev.commentId);
                if (c && c.isDraft) {
                  const span = document.querySelector(`.comment-highlight[data-comment-id="${prev.commentId}"]`);
                  if (span) {
                    const text = document.createTextNode(span.textContent);
                    span.parentNode.replaceChild(text, span);
                  }
                  return cs.filter(x => x.id !== prev.commentId);
                }
                return cs;
              });
            }, 0);
            return { ...prev, open: false };
          }
          return prev;
        });
      }
    };
    document.addEventListener('mousedown', handleOutsideClick);
    document.addEventListener('pointerdown', handleOutsideClick);

    const handleGlobalEscape = (e) => {
      if (e.key === 'Escape') {
        setWorkspaceSwitcherOpen(false);
        if (slashMenuRef.current?.open) {
          setSlashMenu({ open: false, left: 0, top: 0, bottom: 'auto', filterText: '', activeIndex: 0, range: null });
        }
        if (deckSlashMenuRef.current?.open) {
          setDeckSlashMenu({ open: false, left: 0, top: 0, bottom: 'auto', filterText: '', activeIndex: 0, range: null });
        }
        setShowWatermarkMenu(false);
        setLinkPopover(prev => ({ ...prev, open: false }));
        setCommentPopover(prev => {
          if (prev.open) {
            setTimeout(() => {
              setComments(cs => {
                const c = cs.find(x => x.id === prev.commentId);
                if (c && c.isDraft) {
                  const span = document.querySelector(`.comment-highlight[data-comment-id="${prev.commentId}"]`);
                  if (span) {
                    const text = document.createTextNode(span.textContent);
                    span.parentNode.replaceChild(text, span);
                  }
                  return cs.filter(x => x.id !== prev.commentId);
                }
                return cs;
              });
            }, 0);
            return { ...prev, open: false };
          }
          return prev;
        });
        setHoveredCommentId(null);
      }
    };
    window.addEventListener('keydown', handleGlobalEscape);

    return () => {
      delete window.handleEmojiClick;
      delete window.showCreateEmojiForm;
      delete window.showSavedEmojisList;
      document.removeEventListener('mousedown', handleOutsideClick);
      document.removeEventListener('pointerdown', handleOutsideClick);
      window.removeEventListener('keydown', handleGlobalEscape);
    };
  }, []);

  const getCurrentPageNumber = () => {
    try {
      const selection = window.getSelection();
      if (!selection || !selection.rangeCount || !blankBodyRef.current) return 1;
      const range = selection.getRangeAt(0);
      let node = range.startContainer;
      const editor = blankBodyRef.current;
      let pageNum = 1;
      let current = node;
      while (current && current !== editor) {
        if (current.nodeType === 1 && current.getAttribute?.('data-enterprise-page') === 'true') {
          const pages = Array.from(editor.querySelectorAll('[data-enterprise-page="true"]'));
          pageNum = pages.indexOf(current) + 2;
          break;
        }
        current = current.parentNode;
      }
      return pageNum;
    } catch (e) {
      return 1;
    }
  };

  const formatDeckTimer = (totalSeconds) => {
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${minutes}:${seconds < 10 ? '0' : ''}${seconds}`;
  };
  const [deckToolbarFont, setDeckToolbarFont] = useState('Manrope');
  const [deckToolbarMenuOpen, setDeckToolbarMenuOpen] = useState(false);
  const [deckContextRailTab, setDeckContextRailTab] = useState('Design');
  const [deckThemeDropdownOpen, setDeckThemeDropdownOpen] = useState(false);
  const [deckLayoutDropdownOpen, setDeckLayoutDropdownOpen] = useState(false);
  const [deckBrandKitDropdownOpen, setDeckBrandKitDropdownOpen] = useState(false);
  const [deckBgColorPickerOpen, setDeckBgColorPickerOpen] = useState(false);
  const [deckAiSuggestionsExpanded, setDeckAiSuggestionsExpanded] = useState(false);
  const [deckAnimationPreset, setDeckAnimationPreset] = useState('Soft fade and stagger reveal');
  const [deckAnimationSpeed, setDeckAnimationSpeed] = useState('0.5s');
  const [selectedBrandKit, setSelectedBrandKit] = useState(DECK_BRAND_KITS[0]);
