  const applyDirectSelectionStyle = (styles = {}) => {
    let targetRange = null;

    if (savedSelectionRef.current && !savedSelectionRef.current.collapsed) {
      targetRange = savedSelectionRef.current;
    } else {
      const sel = window.getSelection();
      if (sel && sel.rangeCount > 0 && !sel.getRangeAt(0).collapsed) {
        targetRange = sel.getRangeAt(0);
      }
    }

    if (!targetRange) {
      let range = getEditorSelectionRange();
      if (!range && restoreSavedSelection()) {
        range = getEditorSelectionRange();
      }
      targetRange = range;
    }

    if (!targetRange) {
      console.warn('No active target range found for styling');
      return false;
    }

    try {
      const span = document.createElement('span');

      if (styles.removeHighlight) {
        span.style.backgroundColor = 'transparent';
        const frag = targetRange.extractContents();
        span.appendChild(frag);
        span.querySelectorAll('mark, [style*="background"], [style*="background-color"]').forEach(el => {
          el.style.backgroundColor = 'transparent';
          if (el.tagName === 'MARK') {
            const p = el.parentNode;
            if (p) {
              while (el.firstChild) p.insertBefore(el.firstChild, el);
              p.removeChild(el);
            }
          }
        });
        targetRange.insertNode(span);
      } else if (styles.removeColor) {
        span.style.color = 'inherit';
        const frag = targetRange.extractContents();
        span.appendChild(frag);
        span.querySelectorAll('[style*="color"]').forEach(el => {
          el.style.color = 'inherit';
        });
        targetRange.insertNode(span);
      } else {
        if (styles.color) span.style.color = styles.color;
        if (styles.backgroundColor) span.style.backgroundColor = styles.backgroundColor;
        if (styles.fontSize) span.style.fontSize = `${styles.fontSize}px`;
        if (styles.fontFamily) span.style.fontFamily = styles.fontFamily;
        if (styles.fontWeight) span.style.fontWeight = styles.fontWeight;
        if (styles.fontStyle) span.style.fontStyle = styles.fontStyle;
        if (styles.textDecoration) span.style.textDecoration = styles.textDecoration;

        const frag = targetRange.extractContents();
        span.appendChild(frag);
        targetRange.insertNode(span);
      }

      // Update saved selection to surround the styled span
      const nextRange = document.createRange();
      nextRange.selectNodeContents(span);
      savedSelectionRef.current = nextRange.cloneRange();

      const activeSel = window.getSelection();
      if (activeSel) {
        try {
          activeSel.removeAllRanges();
          activeSel.addRange(nextRange);
        } catch (_e) {}
      }

      if (blankBodyRef.current) {
        setDocBodyHtml(blankBodyRef.current.innerHTML);
      }
      return true;
    } catch (err) {
      console.warn('applyDirectSelectionStyle error:', err);
      return false;
    }
  };

  const executeSelectionAiAction = async (actionType, customInstruction = '') => {
    const selText = selectedEditorTextRef.current || selectedEditorText || (typeof window !== 'undefined' ? window.getSelection()?.toString()?.trim() : '') || (savedSelectionRef.current ? savedSelectionRef.current.toString().trim() : '');
    if (!selText) {
      showToast('Please select text first');
      return;
    }

    const rawInstruction = String(customInstruction || selectionAiPrompt || '').trim();

    // 1. Rock-Solid Comprehensive Intent Parser
    if (actionType === 'custom' && rawInstruction) {
      let normalized = rawInstruction.toLowerCase()
        .replace(/\bchnage\b/g, 'change')
        .replace(/\bcolr\b|\bcolour\b|\bcollor\b/g, 'color')
        .replace(/\bhilight\b|\bhighlite\b|\bhightlight\b/g, 'highlight')
        .replace(/\btxt\b/g, 'text');

      // A. Remove Highlight Intent
      if (/(?:remove|clear|strip|delete|no|without)\s+(?:the\s+)?(?:highlight|background|bg|mark)/i.test(normalized)) {
        applyDirectSelectionStyle({ removeHighlight: true });
        setSelectionAiPopoverOpen(false);
        setSelectionActionMenu({ open: false, top: 0, left: 0 });
        setSelectionAiPrompt('');
        showToast('Removed highlight');
        return;
      }

      // B. Remove / Reset Color Intent
      if (/(?:remove|clear|reset|default|no)\s+(?:the\s+)?(?:color|text\s*color)/i.test(normalized)) {
        applyDirectSelectionStyle({ removeColor: true });
        setSelectionAiPopoverOpen(false);
        setSelectionActionMenu({ open: false, top: 0, left: 0 });
        setSelectionAiPrompt('');
        showToast('Reset text color');
        return;
      }

      // C. Check Color Palette & Hex Matches
      const colorWords = Object.keys(COLOR_PALETTE_LOOKUP);
      let matchedColorName = null;
      let matchedHex = null;

      const hexMatch = normalized.match(/#[0-9a-f]{3,8}/i);
      if (hexMatch) {
        matchedColorName = hexMatch[0];
        matchedHex = hexMatch[0];
      } else {
        for (const c of colorWords) {
          const regex = new RegExp(`\\b${c}\\b`, 'i');
          if (regex.test(normalized)) {
            matchedColorName = c;
            matchedHex = COLOR_PALETTE_LOOKUP[c];
            break;
          }
        }
      }

      if (matchedHex) {
        // Is it highlight or text color?
        if (/\b(highlight|background|bg|mark)\b/i.test(normalized)) {
          applyDirectSelectionStyle({ backgroundColor: matchedHex });
          setSelectionAiPopoverOpen(false);
          setSelectionActionMenu({ open: false, top: 0, left: 0 });
          setSelectionAiPrompt('');
          showToast(`Highlighted in ${matchedColorName}`);
          return;
        } else {
          applyDirectSelectionStyle({ color: matchedHex });
          setSelectionAiPopoverOpen(false);
          setSelectionActionMenu({ open: false, top: 0, left: 0 });
          setSelectionAiPrompt('');
          showToast(`Color changed to ${matchedColorName}`);
          return;
        }
      }

      // D. Font Size Intent
      const sizeMatch = normalized.match(/(?:(?:font|text)?\s*size\s*(?:to|of)?\s*|make\s+it\s+)(\d{1,2})(?:px|pt)?/i);
      if (sizeMatch) {
        const nextSize = Number(sizeMatch[1]);
        if (nextSize >= 10 && nextSize <= 72) {
          applyDirectSelectionStyle({ fontSize: nextSize });
          setActiveFontSize(nextSize);
          setSelectionAiPopoverOpen(false);
          setSelectionActionMenu({ open: false, top: 0, left: 0 });
          setSelectionAiPrompt('');
          showToast(`Font size set to ${nextSize}px`);
          return;
        }
      }

      // E. Font Family Intent
      const fontMatch = normalized.match(/(?:change\s+)?font(?:\s+to|:)?\s+([a-z\s]+)/i);
      if (fontMatch) {
        const foundFont = fontOptions.find(f => f.toLowerCase() === fontMatch[1].trim().toLowerCase());
        if (foundFont) {
          applyDirectSelectionStyle({ fontFamily: resolveFontFamily(foundFont) });
          setEditorFont(foundFont);
          setSelectionAiPopoverOpen(false);
          setSelectionActionMenu({ open: false, top: 0, left: 0 });
          setSelectionAiPrompt('');
          showToast(`Font set to ${foundFont}`);
          return;
        }
      }

      // F. Basic Styles Intent
      if (/\b(bold|make\s+it\s+bold|make\s+bold)\b/i.test(normalized)) {
        applyDirectSelectionStyle({ fontWeight: 'bold' });
        setSelectionAiPopoverOpen(false);
        setSelectionActionMenu({ open: false, top: 0, left: 0 });
        setSelectionAiPrompt('');
        showToast('Applied Bold');
        return;
      }
      if (/\b(italic|italicize|make\s+it\s+italic)\b/i.test(normalized)) {
        applyDirectSelectionStyle({ fontStyle: 'italic' });
        setSelectionAiPopoverOpen(false);
        setSelectionActionMenu({ open: false, top: 0, left: 0 });
        setSelectionAiPrompt('');
        showToast('Applied Italic');
        return;
      }
      if (/\b(underline|make\s+it\s+underlined?)\b/i.test(normalized)) {
        applyDirectSelectionStyle({ textDecoration: 'underline' });
        setSelectionAiPopoverOpen(false);
        setSelectionActionMenu({ open: false, top: 0, left: 0 });
        setSelectionAiPrompt('');
        showToast('Applied Underline');
        return;
      }
      if (/\b(strike|strikethrough|cross\s+out)\b/i.test(normalized)) {
        applyDirectSelectionStyle({ textDecoration: 'line-through' });
        setSelectionAiPopoverOpen(false);
        setSelectionActionMenu({ open: false, top: 0, left: 0 });
        setSelectionAiPrompt('');
        showToast('Applied Strikethrough');
        return;
      }
    }

    // 2. Full LLM Transformation Engine with Strict Output Sanitization
    setSelectionAiLoading(true);
    let prompt = '';

    if (actionType === 'improve') {
      prompt = `Rewrite and polish the following text to be clearer, more engaging, and professional:\n\n"${selText}"`;
    } else if (actionType === 'summarize') {
      prompt = `Summarize the following text into concise bullet points:\n\n"${selText}"`;
    } else if (actionType === 'translate') {
      prompt = `Translate the following text into ${customInstruction || selectionAiTranslateLang}:\n\n"${selText}"`;
    } else if (actionType === 'table') {
      prompt = `Convert the key information from the following text into a clean Markdown table with headers and rows:\n\n"${selText}"`;
    } else if (actionType === 'explain') {
      prompt = `Explain what this text means in simple terms and highlight the key takeaways:\n\n"${selText}"`;
    } else if (actionType === 'fix') {
      prompt = `Proofread and fix all grammar, punctuation, and spelling in the following text while preserving its meaning:\n\n"${selText}"`;
    } else {
      prompt = `${rawInstruction}:\n\n"${selText}"`;
    }

    try {
      const response = await callGemini({
        userPrompt: prompt,
        systemPrompt: 'You are the executive writing assistant for Regaarder Compose. Return ONLY the directly transformed text. Do NOT wrap output in markdown code fences (```html). Do NOT include conversational greetings, explanations, or enclosing quotes.',
      });

      let resText = String(response?.text || '').trim();

      // 1. Strip markdown code fences (e.g. ```html ... ```)
      resText = resText.replace(/^```(?:html|markdown|text|json)?\s*\n?/i, '').replace(/\n?```\s*$/i, '').trim();

      // 2. Strip stray leading "html\n"
      resText = resText.replace(/^html\s*\n/i, '').trim();

      // 3. Strip conversational chit-chat prefixes
      resText = resText.replace(/^(?:(?:Okay|Sure|Certainly|Of course|Here is|Here's|I have|I've|I'd be happy to)[^:\n]*:?\s*)+/i, '').trim();

      // 4. Strip unwanted enclosing quotation marks
      if (!selText.startsWith('"') && resText.startsWith('"') && resText.endsWith('"') && resText.length > 2) {
        resText = resText.slice(1, -1).trim();
      }

      if (resText) {
        const formattedHtml = toParagraphHtml(resText);
        const injected = injectIntoSavedSelection(formattedHtml, { injectAsHtml: true });
        if (injected && blankBodyRef.current) {
          setDocBodyHtml(blankBodyRef.current.innerHTML);
          showToast('Updated text with AI');
        } else {
          if (window.__composeInsertHTML) {
            window.__composeInsertHTML(formattedHtml);
          }
        }
      }
    } catch (err) {
      console.warn('Selection AI action error:', err);
      showToast('AI request failed');
    } finally {
      setSelectionAiLoading(false);
      setSelectionAiPopoverOpen(false);
      setSelectionActionMenu({ open: false, top: 0, left: 0 });
      setSelectionAiPrompt('');
    }
  };
  const selectionActionMenuEnabled = true;
  const [documentOutlineItems, setDocumentOutlineItems] = useState([]);
  const [promptAttachments, setPromptAttachments] = useState([]);
  const [assistantAttachments, setAssistantAttachments] = useState([]);
  const [previewAttachment, setPreviewAttachment] = useState(null);
  const [lastComposeRun, setLastComposeRun] = useState(null);
  const [liveSpeechInterimText, setLiveSpeechInterimText] = useState('');
  const [memoryCaptureEnabled, setMemoryCaptureEnabled] = useState(true);
  const [memoryRetentionDays, setMemoryRetentionDays] = useState(90);
  const [memoryEntries, setMemoryEntries] = useState([]);
  const [memoryFilter, setMemoryFilter] = useState('all');
  const [memorySearch, setMemorySearch] = useState('');
  const [lastAiError, setLastAiError] = useState('');
  const [aiBackendStatus, setAiBackendStatus] = useState({ state: 'idle', message: 'Not checked yet' });
  const [chatFeedbackDrafts, setChatFeedbackDrafts] = useState({});
  const [deckSnapshotPreviews, setDeckSnapshotPreviews] = useState({});
  const [sheetSnapshotPreviews, setSheetSnapshotPreviews] = useState({});

  // Smart Input Proofreading Logic
  useEffect(() => {
    const timer = setTimeout(() => {
      if (assistantQuickPrompt && /\b(um|uh)\b/i.test(assistantQuickPrompt)) {
        let cleaned = assistantQuickPrompt.replace(/\b(um|uh)\b/gi, '').replace(/\s+/g, ' ').trim();
        if (cleaned.length > 0) {
          cleaned = cleaned.charAt(0).toUpperCase() + cleaned.slice(1);
          if (!/[.!?]$/.test(cleaned)) cleaned += '.';
          setAssistantQuickPrompt(cleaned);
        }
      }
    }, 1500);
    return () => clearTimeout(timer);
  }, [assistantQuickPrompt]);

  // Context-aware proximity detection: Minimize prompt box into floating button when text/caret or pasted content is within 1-2 lines (~55px)
  useEffect(() => {
    let animationFrameId = null;

    const checkProximity = () => {
      if (isPromptMinimized || isComposing) return;

      const promptInputEl = document.querySelector('textarea[placeholder*="Describe what you\'d like to write"]');
      if (!promptInputEl) return;
      const promptBoxEl = promptInputEl.closest('.fixed');
      if (!promptBoxEl) return;

      const promptRect = promptBoxEl.getBoundingClientRect();
      let isNear = false;

      // 1. Check current selection / caret rect
      const sel = window.getSelection();
      if (sel && sel.rangeCount > 0) {
        const range = sel.getRangeAt(0);
        const rect = range.getBoundingClientRect();
        if (rect && (rect.width > 0 || rect.height > 0 || rect.top > 0)) {
          const verticalGap = promptRect.top - rect.bottom;
          const horizontalOverlap = rect.left <= promptRect.right + 30 && rect.right >= promptRect.left - 30;
          // Apple-style predictive pre-collapse: trigger at 80px gap before text ever physically touches box
          if (verticalGap >= -20 && verticalGap <= 80 && horizontalOverlap) {
            isNear = true;
          }
        }
      }

      // 2. Check editor content bottom element (e.g. for pasted multi-line text blocks)
      if (!isNear && blankBodyRef.current) {
        const children = Array.from(blankBodyRef.current.children);
        if (children.length > 0) {
          for (let i = children.length - 1; i >= 0; i--) {
            const childRect = children[i].getBoundingClientRect();
            if (childRect.height > 0) {
              const verticalGap = promptRect.top - childRect.bottom;
              const horizontalOverlap = childRect.left <= promptRect.right + 30 && childRect.right >= promptRect.left - 30;
              if (verticalGap >= -20 && verticalGap <= 80 && horizontalOverlap) {
                isNear = true;
              }
              break;
            }
          }
        }
      }

      if (isNear) {
        setIsPromptMinimized(true);
      }
    };

    const handleProximityEvent = () => {
      if (animationFrameId) cancelAnimationFrame(animationFrameId);
      animationFrameId = requestAnimationFrame(checkProximity);
    };

    window.addEventListener('scroll', handleProximityEvent, true);
    document.addEventListener('selectionchange', handleProximityEvent);
    document.addEventListener('keyup', handleProximityEvent);
    document.addEventListener('paste', handleProximityEvent);
    document.addEventListener('input', handleProximityEvent);

    return () => {
      if (animationFrameId) cancelAnimationFrame(animationFrameId);
      window.removeEventListener('scroll', handleProximityEvent, true);
      document.removeEventListener('selectionchange', handleProximityEvent);
      document.removeEventListener('keyup', handleProximityEvent);
      document.removeEventListener('paste', handleProximityEvent);
      document.removeEventListener('input', handleProximityEvent);
    };
  }, [isPromptMinimized, isComposing]);
