  const handleCopyLink = async () => {
    const normalizedCode = normalizeRoomCode(roomId) || generateRoomCode();
    if (!roomId) {
      setRoomId(normalizedCode);
      setJoinCode(normalizedCode);
    }
    const link = getMeetingLink(normalizedCode);
    try {
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(link);
      } else {
        const textArea = document.createElement('textarea');
        textArea.value = link;
        document.body.appendChild(textArea);
        textArea.select();
        document.execCommand('copy');
        document.body.removeChild(textArea);
      }
      showToast(`Meeting link copied: ${link}`);
    } catch (_err) {
      showToast('Could not copy link automatically. Please copy from the invite bar.');
    }
  };

  const handleShareMeeting = async () => {
    const normalizedCode = normalizeRoomCode(roomId) || generateRoomCode();
    if (!roomId) {
      setRoomId(normalizedCode);
      setJoinCode(normalizedCode);
    }
    const link = getMeetingLink(normalizedCode);
    const title = 'Join my Regaarder meeting';
    if (navigator.share) {
      try {
        await navigator.share({ title, text: 'Join the call with this link', url: link });
        showToast('Meeting invitation shared');
        return;
      } catch (_error) {
        // Fall through to clipboard behavior.
      }
    }
    await handleCopyLink();
  };

  const inviteCollaborator = async () => {
    const invite = collaboratorInvite.trim();
    if (!invite) {
      showToast('Enter an email or collaborator name first.');
      return;
    }
    await handleShareMeeting();
    setCollaboratorInvite('');
    showToast(`Invitation prepared for ${invite}`);
  };

  const handleMeetingFileSelection = useCallback((files) => {
    const list = Array.from(files || []);
    if (!list.length) {
      return;
    }

    const entries = list.map((file, index) => {
      const baseName = (file?.name || `Shared File ${index + 1}`).replace(/\.[^.]+$/, '');
      const slideCount = Math.min(18, Math.max(6, Math.round((file?.size || 300000) / 90000)));
      return {
        id: `shared-${Date.now()}-${index}`,
        name: file?.name || `Shared File ${index + 1}`,
        baseName,
        type: file?.type || 'application/octet-stream',
        size: file?.size || 0,
        pages: slideCount,
        sharedBy: 'Joshua',
        sharedAt: new Date().toISOString(),
      };
    });

    setSharedMeetingFiles((prev) => [...entries, ...prev]);
    setActiveSharedMeetingFileId(entries[0].id);
    setActiveMeetingStageTab('files');
    showToast(`${entries.length} file${entries.length > 1 ? 's' : ''} shared in meeting`);
  }, []);

  const toggleRoomCamera = async () => {
    const nextOn = !isRoomCameraOn;
    setIsRoomCameraOn(nextOn);
    showToast(nextOn ? 'Camera on' : 'Camera off');

    if (!nextOn) {
      // Turn off camera completely to save privacy & hardware
      if (localStream && !mediaError) {
        localStream.getVideoTracks().forEach(track => {
          track.stop();
          localStream.removeTrack(track);
        });
        setLocalStream(new MediaStream(localStream.getTracks()));
      }
    } else {
      // Re-request camera stream
      if (!mediaError) {
        try {
          const stream = await navigator.mediaDevices.getUserMedia({ video: true });
          if (localStream) {
            const newVideoTrack = stream.getVideoTracks()[0];
            localStream.addTrack(newVideoTrack);
            setLocalStream(new MediaStream(localStream.getTracks()));
          } else {
            setLocalStream(stream);
          }
        } catch (e) {
          console.error("Failed to re-enable camera", e);
          setIsRoomCameraOn(false);
        }
      }
    }
  };

  const toggleRoomMic = async () => {
    const nextOn = !isRoomMicOn;
    setIsRoomMicOn(nextOn);
    setIsMicMuted(!nextOn);
    showToast(nextOn ? "Microphone unmuted (Captions active)" : "Microphone muted");

    if (nextOn) {
      try {
        if (!localStream) {
          const micStream = await navigator.mediaDevices.getUserMedia({ audio: true });
          setLocalStream(micStream);
        } else {
          const audioTracks = localStream.getAudioTracks();
          if (audioTracks.length > 0) {
            audioTracks.forEach(t => { t.enabled = true; });
          } else {
            const micStream = await navigator.mediaDevices.getUserMedia({ audio: true });
            const [audioTrack] = micStream.getAudioTracks();
            if (audioTrack) localStream.addTrack(audioTrack);
          }
        }
      } catch (err) {
        console.warn("[Microphone] Error accessing audio hardware:", err);
      }
    } else {
      if (localStream) {
        localStream.getAudioTracks().forEach(t => { t.enabled = false; });
      }
    }
  };
  const toggleScreenShare = async () => {
    if (isScreenSharing && screenShareStream) {
      screenShareStream.getTracks().forEach((track) => track.stop());
      setScreenShareStream(null);
      setIsScreenSharing(false);
      showToast('Screen sharing stopped');
      return;
    }

    try {
      let stream = null;
      if (window.electronAPI?.getDesktopSources) {
        const sources = await window.electronAPI.getDesktopSources(['screen', 'window']);
        if (sources && sources.length > 0) {
          stream = await navigator.mediaDevices.getUserMedia({
            audio: false,
            video: {
              mandatory: {
                chromeMediaSource: 'desktop',
                chromeMediaSourceId: sources[0].id,
                minWidth: 1280,
                maxWidth: 1920,
                minHeight: 720,
                maxHeight: 1080
              }
            }
          });
        }
      }

      if (!stream && navigator.mediaDevices?.getDisplayMedia) {
        stream = await navigator.mediaDevices.getDisplayMedia({
          video: { cursor: 'always' },
          audio: false,
        });
      }

      if (!stream) {
        throw new Error('Screen capture not supported in this environment');
      }

      const [track] = stream.getVideoTracks();
      if (track) {
        track.onended = () => {
          setIsScreenSharing(false);
          setScreenShareStream(null);
          showToast('Screen sharing stopped');
        };
      }
      setScreenShareStream(stream);
      setIsScreenSharing(true);
      // content protection disabled for smooth screen capture
      showToast('Screen sharing started');
    } catch (err) {
      console.warn('Screen share cancelled or failed:', err);
      if (err.name !== 'NotAllowedError') {
        showToast('Screen share: ' + (err.message || 'Unable to access screen'));
      } else {
        showToast('Screen share cancelled.');
      }
    }
  };

