            <div className="flex items-center gap-1">
              {!isRoomMicOn && <MicOff size={11} className="text-rose-400" />}
              <span className="text-[9px] px-1.5 py-0.5 rounded bg-violet-600/80 text-white font-medium">Host</span>
            </div>
